<?php
declare(strict_types=1);
namespace Nerozon\Database;
final class PdoDatabaseConnector implements DatabaseConnector{private \PDO $pdo;public function __construct(array $c){try{$dsn=sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$c['host'],$c['port']??3306,$c['database']);$this->pdo=new \PDO($dsn,$c['username'],$c['password'],[\PDO::ATTR_ERRMODE=>\PDO::ERRMODE_EXCEPTION,\PDO::ATTR_DEFAULT_FETCH_MODE=>\PDO::FETCH_ASSOC,\PDO::ATTR_EMULATE_PREPARES=>false]);}catch(\PDOException $e){throw new DatabaseUnavailable('Database unavailable',0,$e);}}public function execute(string $s,array $p=[]):WriteResult{try{$q=$this->pdo->prepare($s);$q->execute($p);return new WriteResult($q->rowCount());}catch(\PDOException $e){throw $this->map($e);}}public function fetchOne(string $s,array $p=[]):?array{try{$q=$this->pdo->prepare($s);$q->execute($p);$r=$q->fetch();return $r===false?null:$r;}catch(\PDOException $e){throw $this->map($e);}}public function fetchAll(string $s,array $p=[]):array{try{$q=$this->pdo->prepare($s);$q->execute($p);return $q->fetchAll();}catch(\PDOException $e){throw $this->map($e);}}public function transaction(callable $cb):mixed{try{$this->pdo->beginTransaction();$r=$cb();$this->pdo->commit();return $r;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();if($e instanceof DatabaseException)throw $e;if($e instanceof \PDOException)throw $this->map($e);throw $e;}}public function encodeJson(mixed $v):string{try{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}catch(\JsonException $e){throw new DatabaseSerializationFailure('JSON serialization failed',0,$e);}}public function decodeJson(string $j):mixed{try{return json_decode($j,true,512,JSON_THROW_ON_ERROR);}catch(\JsonException $e){throw new DatabaseSerializationFailure('JSON deserialization failed',0,$e);}}private function map(\PDOException $e):DatabaseException{$state=(string)$e->getCode();if(str_starts_with($state,'23'))return new DatabaseConstraintViolation('Database constraint violation',0,$e);return new DatabaseQueryFailure('Database query failed',0,$e);}}
